//! Header conformance for the synthetic game-information MCP peer.
//!
//! The peer script is generated as a Python source string, so the only honest way to
//! assert what it puts on the wire is to run the generated bytes and read the request
//! a real `http.client` produced. A hand-copied header list would prove nothing: the
//! header this lane removes is injected by CPython rather than written by the script,
//! so re-typing the script's own `headers=` dict cannot observe it.
//!
//! The allow-list below is copied from `sts2-gateway`,
//! `crates/gateway/src/bin/runtime_support/service_authorization.rs` at `cd7e80c6`,
//! `header_is_allowed` (lines 219-241). It is embedded rather than imported because the
//! gateway is a separate repository with no dependency from this test target. If the
//! gateway widens its list, these tests are expected to fail until these names are
//! updated: that failure is the drift alarm, not a bug in the peer.

use super::peer::mcp_server_script;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{SocketAddr, TcpListener};
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::time::Duration;

#[path = "runtime_v3_game_information_entry_peer_headers_wire_tests.rs"]
mod wire_tests;

/// `service_authorization.rs` at `cd7e80c6`, `header_is_allowed`, lines 219-241.
pub(super) const GATEWAY_ALLOWED_HEADERS: &[&str] = &[
    "authorization",
    "connection",
    "content-length",
    "content-type",
    "host",
    "x-mcp-request-id",
    "x-mcp-session-id",
    "x-sts2-instance-id",
    "x-sts2-caller-id",
    "x-sts2-session-id",
    "x-sts2-lease-id",
    "x-sts2-lease-epoch",
    "x-sts2-workflow-boot-epoch",
    "x-sts2-correlation-id",
    "x-sts2-capabilities-version",
    "x-sts2-episode-profile",
    "x-sts2-peer-token",
    "x-sts2-recovery-capability",
];

/// A header the peer must never grow: the fix is scoped suppression, not a wider
/// header set, so a "just send everything" edit has to fail here.
pub(super) const UNSET_HEADER_SENTINEL: &str = "x-sts2-capabilities-version";

/// Both gateway call sites in the generated script. `query_response` and
/// `bootstrap_proxy` post independently, so each is probed on the real wire rather
/// than inferred from a source count.
pub(super) const GATEWAY_TOOLS: &[&str] = &[
    "sts2.game_information_detail",
    "sts2.game_information.live_observation_bootstrap",
];

/// The request line each probe tool must still produce. Suppression must not
/// disturb routing.
pub(super) const GATEWAY_PATHS: &[(&str, &str)] = &[
    (
        "sts2.game_information_detail",
        "/v1/instances/instance-1/game-information/detail",
    ),
    (
        "sts2.game_information.live_observation_bootstrap",
        "/v1/instances/instance-1/game-information/live-observation-bootstrap",
    ),
];

fn python() -> PathBuf {
    std::fs::canonicalize("/usr/bin/python3").expect("Python interpreter for the peer")
}

pub(super) fn temporary_directory(name: &str) -> PathBuf {
    // Tests run in parallel threads inside one process, and several probe the same
    // tool. A directory keyed only on tool name is therefore shared: one test
    // would `remove_dir_all` the script another test had just written, and that
    // test's spawn would then fail or, worse, run the wrong script. An atomic
    // counter makes every call unique regardless of thread.
    static SEQUENCE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let sequence = SEQUENCE.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let root = std::env::temp_dir().join(format!(
        "sts2-peer-headers-{}-{}-{sequence}",
        name,
        std::process::id()
    ));
    std::fs::create_dir_all(&root).expect("temporary peer-header directory");
    root
}

/// Remove Python `#` comments from generated script text so a search for a header
/// name inspects executable code only.
///
/// The peer script is embedded in a Rust string literal, so it is a single logical
/// line containing embedded newlines. Comment stripping therefore has to work on
/// the decoded text, and it deliberately does not try to understand Python string
/// quoting: the only `#` characters in this script are comment markers, and a
/// `#` inside a string would merely be preserved, never dropped, so the result is
/// a superset of the executable text and the assertion stays conservative.
pub(super) fn strip_python_comments(source: &str) -> String {
    let mut stripped = String::with_capacity(source.len());
    for line in source.lines() {
        let executable = match line.find('#') {
            Some(index) => &line[..index],
            None => line,
        };
        stripped.push_str(executable);
        stripped.push('\n');
    }
    stripped
}

/// One request exactly as a listener received it: the raw request line and headers,
/// plus the declared body length.
#[derive(Debug)]
pub(super) struct CapturedRequest {
    request_line: String,
    headers: Vec<(String, String)>,
}

impl CapturedRequest {
    fn names(&self) -> Vec<String> {
        self.headers
            .iter()
            .map(|(name, _)| name.to_ascii_lowercase())
            .collect()
    }

    fn value(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(header, _)| header.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.as_str())
    }
}

/// A loopback listener that speaks just enough HTTP/1.1 to capture one request and
/// answer it. It never inspects the allow-list: these tests assert on the bytes the
/// peer emitted, so a request the gateway would refuse still arrives here intact and
/// can be compared against the allow-list by the test.
fn capture_one_request() -> (SocketAddr, mpsc::Receiver<CapturedRequest>) {
    let (sender, receiver) = mpsc::channel();
    // Bind on the calling thread and hand the live listener to the worker. The
    // obvious alternative — bind, read the address, drop, rebind in the worker —
    // is a race: the kernel may hand the same ephemeral port to a parallel test
    // in between, and the worker's bind then fails, the channel closes, and the
    // test fails as a 20s timeout with no indication of the real cause.
    let listener = TcpListener::bind("127.0.0.1:0").expect("bind loopback listener");
    // Read the address here, before the listener is moved into the worker thread.
    // The port stays reserved for the life of the probe because the worker holds
    // the bound listener itself.
    let address = listener.local_addr().expect("loopback address");
    std::thread::spawn(move || {
        let (mut socket, _) = match listener.accept() {
            Ok(accepted) => accepted,
            Err(_) => return,
        };
        let mut reader = BufReader::new(match socket.try_clone() {
            Ok(clone) => clone,
            Err(_) => return,
        });
        let mut request_line = String::new();
        if reader.read_line(&mut request_line).is_err() {
            return;
        }
        let mut headers: Vec<(String, String)> = Vec::new();
        loop {
            let mut line = String::new();
            if reader.read_line(&mut line).is_err() {
                return;
            }
            let trimmed = line.trim_end_matches(['\r', '\n']);
            if trimmed.is_empty() {
                break;
            }
            if let Some((name, value)) = trimmed.split_once(':') {
                headers.push((name.trim().to_string(), value.trim().to_string()));
            }
        }
        let length: usize = headers
            .iter()
            .find(|(name, _)| name.eq_ignore_ascii_case("content-length"))
            .and_then(|(_, value)| value.parse().ok())
            .unwrap_or(0);
        if length > 0 {
            let mut body = vec![0_u8; length];
            if reader.read_exact(&mut body).is_err() {
                return;
            }
        }
        let body = br#"{"protocol_version":"game-information-query-v1","kind":"query_response","result":{"page":{"items":[],"final_page":true}},"correlation_id":"7"}"#;
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n",
            body.len()
        );
        let _ = socket.write_all(response.as_bytes());
        let _ = socket.write_all(body);
        let _ = socket.flush();
        let _ = sender.send(CapturedRequest {
            request_line,
            headers,
        });
    });
    (address, receiver)
}

/// Drive the *generated* peer script through one live-observation tool call and return
/// the request it put on the wire.
///
/// The script is written to disk by `mcp_server_script` exactly as the fixture setup
/// writes it, then executed by the pinned interpreter. No part of the request is
/// re-derived in Rust.
pub(super) fn peer_request_for(tool: &str) -> CapturedRequest {
    // The worker holds the bound listener for the life of the probe, so a parallel
    // test cannot take the port between reservation and accept.
    let (address, captured) = capture_one_request();
    let root = temporary_directory(tool);
    let script = root.join("entry-mcp.py");
    let log = root.join("entry-mcp.jsonl");
    std::fs::write(&script, mcp_server_script(&log)).expect("write generated peer script");

    let mut child = Command::new(python())
        .arg(&script)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("STS2_GATEWAY_ADDR", address.to_string())
        .env("STS2_SESSION_ID", "session-1")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("spawn generated peer script");

    let arguments = match tool {
        "sts2.game_information_detail" => serde_json::json!({
            "instance_id": "instance-1",
            "mcp_session_id": "mcp-session-1",
            "lease_id": "lease-1",
            "lease_epoch": 1,
            "correlation_id": "7",
            "instance_ref": "instance-1:0",
            "definition_ref": {
                "content_manifest_id": "content-1",
                "entity_kind": "card",
                "namespaced_id": "ironclad:strike",
                "variant": null
            },
            "namespaced_ids": [],
            "definition_refs": [],
            "instance_ids": [],
            "projection": "summary",
            "detail_level": "summary",
            "fields": ["display_name"],
            "content_manifest_id": "content-1",
            "locale": "en-US",
            "page_items": 4,
            "item_bytes": 4096,
            "page_bytes": 65536,
            "text_bytes": 4096,
            "cursor": null
        }),
        // The bootstrap call site is the *second* of the two gateway posts, so it needs
        // its own wire coverage: a fix applied to `query_response` alone would leave this
        // one still refused. The generated script's `elif` chain uses the full dotted
        // name, so the probe must send the same name the real dispatcher does.
        "sts2.game_information.live_observation_bootstrap" => serde_json::json!({
            "instance_id": "instance-1",
            "mcp_session_id": "mcp-session-1",
            "lease_id": "lease-1",
            "lease_epoch": 1,
            "correlation_id": "7",
            "instance_ref": "instance-1:0",
            "definition_ref": {
                "content_manifest_id": "content-1",
                "entity_kind": "card",
                "namespaced_id": "ironclad:strike",
                "variant": null
            },
            "content_manifest_id": "content-1",
            "locale": "en-US"
        }),
        other => panic!("unsupported probe tool: {other}"),
    };
    let request = serde_json::json!({
        "jsonrpc": "2.0",
        "id": 7,
        "method": "tools/call",
        "params": { "name": tool, "arguments": arguments }
    });
    child
        .stdin
        .take()
        .expect("peer stdin")
        .write_all(format!("{request}\n").as_bytes())
        .expect("drive peer script");

    let request = captured
        .recv_timeout(Duration::from_secs(20))
        .expect("the peer must issue a gateway request for a live-observation tool");
    let _ = child.kill();
    let _ = child.wait();
    let _ = std::fs::remove_dir_all(&root);
    request
}
